"""lab：給學生程式用的 API（在板子上執行）。

    import lab
    lab.sleep(0.5)            # 可被「停止」中斷的 sleep（請用這個，不要用 time.sleep）
    while lab.running(): ...  # 停止鍵按下後變 False
    lab.display.text("Hi", 0, 0); lab.display.show()   # T-QT Pro 螢幕（DevKit 上只記錄文字）
    lab.send(temp=25.3)       # 把數值送到 App 的主控台／感測值列
    lab.on_cmd(fn)            # 收 App 遙控頁的指令：fn({"op":"joy","x":..,"y":..})
    lab.led(1)                # 板載 LED（DevKit GPIO2；T-QT Pro 無 LED 時改亮螢幕角落）
"""
import time as _time

__version__ = "0.5.1"


class StopRequested(Exception):
    """停止鍵按下後，lab.sleep() 會丟出這個例外來結束程式。"""
    pass


_stop = False
_cmd_handler = None
_cmd_queue = []          # App／IDE 送來的指令先排隊，由學生程式的執行緒在 lab.sleep()／lab.running() 時處理
                         # （處理函式若畫圖或等待，才不會卡住代理程式的伺服器）
_out_queue = []          # 由 runner／server 消費
display = None           # 由 lab.agent 依板子型號設定
board = "generic"
_pins = {}


class _CameraProxy:
    """lab.camera.snapshot()：延後載入 lab.camera，沒有相機的板子也能 import lab。"""
    def __getattr__(self, name):
        from lab import camera as _c
        return getattr(_c, name)


camera = _CameraProxy()


def _drain_cmds():
    """在學生程式的執行緒裡執行排隊中的遙控／視覺指令。"""
    while _cmd_queue:
        cmd = _cmd_queue.pop(0)
        if cmd.get("op") == "led" and cmd.get("_builtin"):
            led(cmd.get("v")); continue
        if _cmd_handler:
            try:
                _cmd_handler(cmd)
            except StopRequested:
                raise
            except Exception as e:
                emit("err", s="on_cmd 處理錯誤：%r\n" % e)


def running():
    _drain_cmds()
    return not _stop


def sleep(seconds):
    """像 time.sleep，但每 50 ms 檢查停止旗標，並處理排隊中的指令。"""
    end = _time.ticks_add(_time.ticks_ms(), int(seconds * 1000))
    while True:
        _drain_cmds()
        if _stop:
            raise StopRequested()
        left = _time.ticks_diff(end, _time.ticks_ms())
        if left <= 0:
            break
        _time.sleep_ms(min(50, max(1, left)))
    if _stop:
        raise StopRequested()


def emit(t, **kw):
    """內部用：排一則訊息給所有連線中的 App。"""
    kw["t"] = t
    _out_queue.append(kw)
    if len(_out_queue) > 200:
        del _out_queue[:50]


def log(*args):
    s = " ".join(str(a) for a in args)
    print(s)
    emit("out", s=s + "\n")


def send(**values):
    """把感測值送到 App：lab.send(temp=25.3, light=512)"""
    emit("sensor", v=values)


def on_cmd(fn):
    global _cmd_handler
    _cmd_handler = fn
    return fn


def _dispatch_cmd(cmd):
    """由伺服器呼叫：只排隊，不在伺服器執行緒執行學生的處理函式。"""
    if _cmd_handler:
        _cmd_queue.append(cmd)
        if len(_cmd_queue) > 50:
            del _cmd_queue[:25]


def _led_from_server(v):
    """遙控頁的 LED 開關：學生程式在跑時排隊到它的執行緒（避免兩個執行緒同時畫螢幕），沒跑時直接做。"""
    from lab import runner
    if runner.is_running():
        _cmd_queue.append({"op": "led", "v": v, "_builtin": True})
    else:
        led(v)


def rssi():
    """Wi-Fi 訊號強度 dBm（沒連上回 None）。"""
    try:
        import network
        sta = network.WLAN(network.STA_IF)
        return sta.status("rssi") if sta.isconnected() else None
    except Exception:
        return None


def battery():
    """電池電壓（伏特）；T-QT Pro 由 GPIO4 分壓讀取，其他板子回 None。"""
    if board != "tqt_pro":
        return None
    try:
        from machine import ADC, Pin
        a = ADC(Pin(4), atten=ADC.ATTN_11DB)
        v = a.read_uv() / 1_000_000 * 2
        return round(v, 2)
    except Exception:
        return None


def pin(n, mode="out"):
    from machine import Pin
    key = (n, mode)
    if key not in _pins:
        _pins[key] = Pin(n, Pin.OUT if mode == "out" else Pin.IN)
    return _pins[key]


def led(v):
    """板載 LED；沒有 LED 的板子：有螢幕就亮右上角小方塊，否則送訊息到主控台。"""
    from lab import boards
    p = boards.LED_PIN.get(board)
    if p is None:
        if display is not None and hasattr(display, "buf"):
            display.fill_rect(120, 0, 8, 8, display.WHITE if v else display.BLACK)
            display.show()
        else:
            emit("sensor", v={"led": 1 if v else 0})
        return
    on = 1 if v else 0
    if boards.LED_INVERTED.get(board):
        on ^= 1
    pin(p).value(on)

