"""代理程式主體：Wi-Fi、HTTP／WebSocket API、心跳。"""
import asyncio
import gc
import json
import os
import sys
import time
import machine
import lab
from lab import wifi, runner, gpio
from microdot import Microdot, Response, send_file
from microdot.websocket import with_websocket

app = Microdot()
from microdot import Request
Request.max_content_length = 320 * 1024
Request.max_body_length = 320 * 1024
Response.default_content_type = "application/json"
_clients = []
_last_cmd = {}
_boot = time.time()
_mode, _ip = None, None


def _board():
    """板型＝首燒寫入的 board.json，沒有就依晶片家族（os.uname）給預設。"""
    from lab import boards
    val = None
    try:
        with open("board.json") as f:
            val = json.load(f).get("board")
    except Exception:
        pass
    b, chip = boards.resolve(val)
    lab.chip = chip
    return b


def _setup_display():
    from lab import board_tqt, boards
    if boards.BOARDS.get(lab.board, {}).get("display_driver") == "board_tqt":
        try:
            lab.display = board_tqt.Display()
            return
        except Exception as e:
            print("display init failed:", e)
    lab.display = board_tqt.DummyDisplay()


def _ensure_dir(d):
    try:
        os.mkdir(d)
    except OSError:
        pass


@app.get("/info")
async def info(req):
    return {"name": wifi.hostname(), "id": wifi.device_id(), "board": lab.board, "chip": getattr(lab, "chip", "?"), "ip": _ip,
            "mode": _mode, "version": lab.__version__, "micropython": sys.version,
            "status": runner.state["status"], "file": runner.state["file"], "rssi": _rssi(),
            "uptime": time.time() - _boot, "free": gc.mem_free(), "clients": len(_clients)}


@app.post("/run")
async def run(req):
    code = req.body.decode()
    name = req.args.get("name", "main.py")
    _ensure_dir("user")
    with open("user/" + name, "w") as f:
        f.write(code)
    ok, msg = runner.start(code, "user/" + name)
    return {"ok": ok, "msg": msg}, (200 if ok else 409)


@app.post("/check")
async def check(req):
    """只做語法檢查（用板子自己的 MicroPython 編譯器），不執行。"""
    code = req.body.decode()
    try:
        compile(code, req.args.get("name", "main.py"), "exec")
        return {"ok": True}
    except SyntaxError as e:
        # MicroPython 的 SyntaxError 沒帶行號屬性，從 print_exception 的 'line N' 解析
        import io
        buf = io.StringIO()
        sys.print_exception(e, buf)
        line = None
        for part in buf.getvalue().split("\n"):
            if "line " in part and '", line' in part:
                try:
                    line = int(part.split('", line')[1].split(",")[0].strip())
                except ValueError:
                    pass
        return {"ok": False, "line": line, "msg": str(e)}
    except Exception as e:
        return {"ok": False, "line": None, "msg": repr(e)}


@app.post("/stop")
async def stop(req):
    st = runner.stop()
    for _ in range(40):          # 最多等 2 秒讓程式自己結束
        if not runner.is_running():
            break
        await asyncio.sleep_ms(50)
    return {"ok": not runner.is_running(), "was": st, "status": runner.state["status"]}


@app.post("/reset")
async def reset(req):
    async def later():
        await asyncio.sleep_ms(300)
        machine.reset()
    asyncio.create_task(later())
    return {"ok": True}


@app.get("/files")
async def files(req):
    _ensure_dir("user")
    out = []
    for name in os.listdir("user"):
        st = os.stat("user/" + name)
        out.append({"name": name, "size": st[6]})
    return out


@app.get("/files/<name>")
async def get_file(req, name):
    try:
        return send_file("user/" + name, content_type="text/plain; charset=utf-8")
    except OSError:
        return {"error": "not found"}, 404


@app.put("/files/<name>")
async def put_file(req, name):
    _ensure_dir("user")
    with open("user/" + name, "w") as f:
        f.write(req.body.decode())
    return {"ok": True}


@app.delete("/files/<name>")
async def del_file(req, name):
    try:
        os.remove("user/" + name)
        return {"ok": True}
    except OSError:
        return {"error": "not found"}, 404


@app.get("/screen.bmp")
async def screen(req):
    if not hasattr(lab.display, "buf"):
        return {"error": "no display"}, 404
    return Response(body=lab.display.bmp(), headers={"Content-Type": "image/bmp"})


@app.get("/camera.jpg")
async def camera_jpg(req):
    """最近一張 lab.camera.snapshot() 的照片；?fresh=1 會現拍一張。"""
    if req.args.get("fresh"):
        try:
            from lab import camera
            camera.snapshot()
        except Exception as e:
            return {"error": str(e)}, 500
    try:
        resp = send_file("user/last.jpg", content_type="image/jpeg", max_age=0)
        resp.headers["Access-Control-Allow-Origin"] = "*"   # 視覺頁要能把這張圖畫進 canvas 做辨識
        return resp
    except OSError:
        return {"error": "還沒拍過照：先執行 lab.camera.snapshot()"}, 404


@app.post("/cmd")
async def cmd_http(req):
    gpio.handle(req.json or {})
    return {"ok": True}


@app.post("/wifi")
async def set_wifi(req):
    data = req.json or {}
    cfg = wifi.load()
    for k in ("ssid", "pass", "server"):
        if k in data:
            cfg[k] = data[k]
    wifi.save(cfg)
    asyncio.create_task(_reset_later())
    return {"ok": True, "hostname": wifi.hostname() + ".local"}


async def _reset_later():
    await asyncio.sleep_ms(500)
    machine.reset()


@app.get("/")
async def index(req):
    # 已連上 Wi-Fi 且有 IDE 檔 → 直接進網頁版 IDE；否則是 Wi-Fi 設定頁
    if _mode == "sta":
        try:
            os.stat("ide.html")
            return Response.redirect("/ide")
        except OSError:
            pass
    return Response(body=_INDEX % (wifi.hostname(), lab.board), headers={"Content-Type": "text/html; charset=utf-8"})


@app.get("/setup")
async def setup(req):
    return Response(body=_INDEX % (wifi.hostname(), lab.board), headers={"Content-Type": "text/html; charset=utf-8"})


@app.get("/ide")
async def ide(req):
    try:
        return send_file("ide.html", content_type="text/html; charset=utf-8", max_age=0)
    except OSError:
        return {"error": "ide.html not installed"}, 404


@app.post("/update")
async def update(req):
    """Wi-Fi 更新代理程式：body＝agent_bundle.json（{version, files:{path:text}}）。
    先寫成 .new 再改名，最後重開；回應後 0.5 秒重開。"""
    data = req.json
    if not data or "files" not in data:
        return {"ok": False, "msg": "bundle 格式錯誤"}, 400
    written = []
    try:
        if hasattr(lab.display, "buf"):
            from lab import screen
            screen.draw_updating(lab.display, data.get("version"))
    except Exception:
        pass
    try:
        for path, text in data["files"].items():
            if "/" in path:
                _ensure_dir(path.rsplit("/", 1)[0])
            with open(path + ".new", "w") as f:
                f.write(text)
            written.append(path)
        for path in written:
            try:
                os.remove(path)
            except OSError:
                pass
            os.rename(path + ".new", path)
    except Exception as e:
        for path in written:
            try:
                os.remove(path + ".new")
            except OSError:
                pass
        return {"ok": False, "msg": "寫入失敗：%r" % e, "free": gc.mem_free()}, 500
    asyncio.create_task(_reset_later())
    return {"ok": True, "from": lab.__version__, "to": data.get("version"), "files": len(written)}


_INDEX = """<!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width">
<title>ESP32 AI Lab</title><body style="font-family:sans-serif;max-width:420px;margin:2em auto">
<h2>%s</h2><p>板子：%s</p>
<form onsubmit="event.preventDefault();fetch('/wifi',{method:'POST',headers:{'Content-Type':'application/json'},
body:JSON.stringify({ssid:ssid.value,pass:pw.value,server:srv.value})}).then(r=>r.json()).then(j=>msg.textContent='已儲存，板子重開中，稍後連 '+j.hostname)">
<p><label>Wi-Fi 名稱 <input id=ssid required></label></p>
<p><label>Wi-Fi 密碼 <input id=pw type=password></label></p>
<p><label>教室伺服器（可空）<input id=srv placeholder="http://192.168.1.10:8765"></label></p>
<button>儲存並重開</button></form><p id=msg></p>
<p><a href="/info">/info</a> · <a href="/screen.bmp">/screen.bmp</a></p>"""


@app.route("/ws")
@with_websocket
async def ws(req, ws):
    _clients.append(ws)
    try:
        await ws.send(json.dumps({"t": "hello", "name": wifi.hostname(), "board": lab.board,
                                  "status": runner.state["status"]}))
        while True:
            msg = await ws.receive()
            try:
                data = json.loads(msg)
            except ValueError:
                continue
            t = data.get("t")
            if t == "cmd":
                op = data.get("op")
                if op in ("vision", "joy"):
                    now = time.ticks_ms()
                    gap = 100 if op == "vision" else 50
                    if time.ticks_diff(now, _last_cmd.get(op, 0)) < gap:
                        continue            # 板端節流：App／IDE 送太快時丟掉，不排隊
                    _last_cmd[op] = now
                gpio.handle(data)
            elif t == "run":
                ok, m = runner.start(data.get("code", ""), "user/" + data.get("name", "main.py"))
            elif t == "stop":
                runner.stop()
            elif t == "ping":
                await ws.send(json.dumps({"t": "pong"}))
    finally:
        if ws in _clients:
            _clients.remove(ws)


async def _pump():
    """把 lab._out_queue 的訊息送給所有 WebSocket 客戶端。"""
    while True:
        if lab._out_queue and _clients:
            batch = lab._out_queue[:]
            del lab._out_queue[:len(batch)]
            for m in batch:
                s = json.dumps(m)
                for c in _clients[:]:
                    try:
                        await c.send(s)
                    except Exception:
                        if c in _clients:
                            _clients.remove(c)
        elif lab._out_queue and not _clients and len(lab._out_queue) > 100:
            del lab._out_queue[:50]
        await asyncio.sleep_ms(30)


async def _beacon():
    cfg = wifi.load()
    url = cfg.get("server")
    if not url or _mode != "sta":
        return
    try:
        import requests
    except ImportError:
        return
    while True:
        try:
            r = requests.post(url.rstrip("/") + "/devices/heartbeat", json={
                "name": wifi.hostname(), "id": wifi.device_id(), "ip": _ip, "board": lab.board,
                "status": runner.state["status"], "version": lab.__version__}, timeout=3)
            r.close()
        except Exception:
            pass
        await asyncio.sleep(5)


def _rssi():
    try:
        import network
        sta = network.WLAN(network.STA_IF)
        return sta.status("rssi") if sta.isconnected() else None
    except Exception:
        return None


def _splash():
    d = lab.display
    if not hasattr(d, "buf"):      # 沒有螢幕的板子：文字版
        if _mode == "sta":
            d.print_lines(["ESP32 AI Lab", wifi.hostname() + ".local", _ip, "ready"])
        else:
            d.print_lines(["ESP32 AI Lab", "AP ESP32LAB-" + wifi.device_id(), "pw esp32lab", "http://" + _ip])
        return
    from lab import screen
    if _mode == "sta":
        screen.draw_idle(d, wifi.hostname(), _ip, _rssi(), runner.state["status"], runner.state["file"])
    else:
        screen.draw_ap(d, "ESP32LAB-" + wifi.device_id(), _ip)


async def _watchdog():
    """硬體看門狗：伺服器事件迴圈每 5 秒餵一次；SPI 鎖死或任何讓迴圈停擺超過 60 秒的狀況會自動重開，
    避免再出現「整顆卡死連 USB 都掛」。同時每 30 秒做一次 gc 並回報記憶體到序列埠。"""
    try:
        wdt = machine.WDT(timeout=60000)
    except Exception as e:
        print("WDT unavailable:", e)
        return
    n = 0
    while True:
        wdt.feed()
        n += 1
        if n % 6 == 0:
            gc.collect()
            if gc.mem_free() < 40000:
                print("low memory:", gc.mem_free())
        await asyncio.sleep(5)


async def _idle_screen():
    """待機畫面：狀態改變時重畫；程式結束 2 秒後回到待機；待命中每 10 秒更新訊號。學生程式執行中不碰螢幕。"""
    last = None
    tick = 0
    while True:
        await asyncio.sleep_ms(500)
        st = runner.state["status"]
        if st == "running":
            last = "running"
            tick = 0
            continue
        tick += 1
        if last == "running":            # 剛結束：讓學生看 2 秒結果再回待機
            await asyncio.sleep(2)
            if runner.state["status"] == "running":
                continue
            _splash(); last = "idle"; tick = 0
        elif last is None or tick >= 20:
            _splash(); last = "idle"; tick = 0


def main():
    global _mode, _ip
    lab.board = _board()
    _setup_display()
    try:
        from lab import screen
        if hasattr(lab.display, "buf"):
            screen.draw_connecting(lab.display, wifi.load().get("ssid", "") or "（未設定）")
        else:
            lab.display.print_lines(["ESP32 AI Lab", "connecting Wi-Fi..."])
    except Exception as e:
        print("splash failed:", e)
    _mode, _ip = wifi.connect()
    print("esp32-ai-lab %s mode=%s ip=%s host=%s.local board=%s" % (lab.__version__, _mode, _ip, wifi.hostname(), lab.board))
    _splash()
    _ensure_dir("user")

    async def serve():
        asyncio.create_task(_pump())
        asyncio.create_task(_beacon())
        asyncio.create_task(_idle_screen())
        asyncio.create_task(_watchdog())
        await app.start_server(host="0.0.0.0", port=80, debug=False)
    asyncio.run(serve())

