"""相機（社群 camera 模組，cnadler86/micropython-camera-API）。
lab.camera.snapshot() → JPEG bytes；同時存成 user/last.jpg 並送 {"t":"image","url":"/camera.jpg?..."} 給 IDE 顯示縮圖。
沒有相機模組的板子呼叫會丟 RuntimeError（主控台看得到原因）。"""
import time
import lab

_cam = None


def _get():
    global _cam
    if _cam is None:
        try:
            from camera import Camera, PixelFormat, FrameSize
        except ImportError:
            raise RuntimeError("這塊板子的韌體沒有相機模組（要燒 ESP32-CAM 相機版韌體）")
        _cam = Camera(pixel_format=PixelFormat.JPEG, frame_size=FrameSize.QVGA, jpeg_quality=85, init=True)
    return _cam


def snapshot(save="user/last.jpg", quality=None):
    cam = _get()
    if quality is not None:
        try:
            cam.set_quality(quality)
        except Exception:
            pass
    data = cam.capture()
    if not data:
        raise RuntimeError("拍照失敗（鏡頭沒回資料）")
    if save:
        with open(save, "wb") as f:
            f.write(data)
        lab.emit("image", url="/camera.jpg?t=%d" % time.ticks_ms(), size=len(data))
    return data


def release():
    global _cam
    if _cam is not None:
        try:
            _cam.deinit()
        except Exception:
            pass
        _cam = None

