"""Realtek Ameba（RTL8722DM／BW16，AmebaD MicroPython 移植）的相容層——**只做靜態設計，未在實機驗證**。
AmebaD 的 MicroPython 用 `wireless.WLAN(mode=WLAN.STA)`，沒有 `network` 模組、沒有 `network.hostname()`；
asyncio 是否存在官方頁面沒寫（2026-10-31 查證，見 docs/Ameba評估.md）。
用法：在 boot.py 最前面 `import lab.compat_ameba`，它會：
1. 若沒有 `network` 模組但有 `wireless`，安裝一個最小的 `network` 替身（STA_IF／AP_IF／WLAN.active/connect/isconnected/ifconfig/status/config，hostname() 只記住不生效）。
2. 若沒有 asyncio，代理程式無法啟動（Microdot 需要 asyncio），會印出明確訊息。"""
import sys

try:
    import network  # noqa: F401
except ImportError:
    try:
        from wireless import WLAN as _AmebaWLAN
    except ImportError:
        _AmebaWLAN = None
    if _AmebaWLAN is not None:
        class _NetworkShim:
            STA_IF = 0
            AP_IF = 1
            AUTH_WPA_WPA2_PSK = 3
            _hostname = None

            @staticmethod
            def hostname(h=None):
                if h is not None:
                    _NetworkShim._hostname = h
                return _NetworkShim._hostname

            class WLAN:
                PM_NONE = 0

                def __init__(self, iface):
                    self._iface = iface
                    self._w = _AmebaWLAN(mode=_AmebaWLAN.STA if iface == 0 else _AmebaWLAN.AP)
                    self._on = False
                    self._ssid = None

                def active(self, v=None):
                    if v is not None:
                        self._on = bool(v)
                    return self._on

                def config(self, **kw):
                    if "essid" in kw:
                        self._ssid = kw["essid"]
                        self._pw = kw.get("password", "")
                        try:
                            self._w.start_ap(ssid=self._ssid, pswd=self._pw)
                        except Exception:
                            pass

                def connect(self, ssid, pw=""):
                    self._w.connect(ssid=ssid, pswd=pw)

                def isconnected(self):
                    try:
                        return bool(self._w.is_connect_to_ap())
                    except Exception:
                        return False

                def ifconfig(self):
                    try:
                        return (self._w.get_ip(), "255.255.255.0", "0.0.0.0", "8.8.8.8")
                    except Exception:
                        return ("0.0.0.0", "255.255.255.0", "0.0.0.0", "8.8.8.8")

                def status(self, key=None):
                    if key == "rssi":
                        try:
                            return self._w.rssi()
                        except Exception:
                            return None
                    return 1 if self.isconnected() else 0

