"""Wi-Fi：有 wifi.json 就連 STA；沒有或連不上就開 AP 讓手機填。"""
import json
import network
import time
import ubinascii
import machine

CFG = "wifi.json"


def device_id():
    return ubinascii.hexlify(machine.unique_id()).decode()[-4:]


def hostname():
    return "esp32lab-" + device_id()


def load():
    try:
        with open(CFG) as f:
            return json.load(f)
    except Exception:
        return {}


def save(cfg):
    with open(CFG, "w") as f:
        json.dump(cfg, f)


def connect(timeout=20):
    """回傳 (mode, ip)；mode 為 'sta' 或 'ap'。"""
    cfg = load()
    network.hostname(hostname())
    sta = network.WLAN(network.STA_IF)
    if cfg.get("ssid"):
        sta.active(True)
        try:
            sta.config(pm=network.WLAN.PM_NONE)   # 關省電，WebSocket 才不會延遲
        except Exception:
            pass
        sta.connect(cfg["ssid"], cfg.get("pass", ""))
        t0 = time.ticks_ms()
        while not sta.isconnected() and time.ticks_diff(time.ticks_ms(), t0) < timeout * 1000:
            time.sleep_ms(200)
        if sta.isconnected():
            return "sta", sta.ifconfig()[0]
        sta.active(False)
    ap = network.WLAN(network.AP_IF)
    ap.active(True)
    ap.config(essid="ESP32LAB-" + device_id(), password="esp32lab", authmode=network.AUTH_WPA_WPA2_PSK)
    return "ap", ap.ifconfig()[0]
